#include <jwt.h>
#include <string>
#include <stdexcept>

std::string decode_json_web_token(const std::string& token, const std::string& key) {
    if (token.empty() || key.empty()) {
        return "{}";
    }

    jwt_t* decoded_token = nullptr;
    int result = jwt_decode(&decoded_token, token.c_str(), key.c_str(), JWT_VERIFY_NONE);

    if (result != 0 || !decoded_token) {
        return "{}";
    }

    char* claims_json = jwt_dump_plaintext_decoded(decoded_token);
    std::string claims(claims_json ? claims_json : "");
    free(claims_json);
    jwt_free_decoded_token(decoded_token);

    return claims.empty() ? "{}" : claims;
}
